    /// <summary>
    /// Enables a proxy. Only one proxy can be enabled at a time. Can be called before authorization
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> EnableProxyAsync(int proxyId = default)
    {

           using var activity =  StartCallActivity("EnableProxyAsync", typeof(EnableProxy).FullName ?? "EnableProxyAsync");

           try
           {
             return client.EnableProxyAsync(proxyId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
